  'room.cocina.desc': 'Beslenme: öğünlerini, makrolarını, suyunu ve haftalık planını kaydet.',
  'room.ejercicio.desc': 'Hedefli güç, dayanıklılık ve esneklik rutinleri.',
  'room.recamara.desc': 'Dinlenmeni takip et ve kişisel anı defterini yaz.',
  'room.descanso.desc': 'Uykun bir gece göğü gibi: program, alarm, puan ve gece kaydı.',
  'room.anecdotario.desc': 'Anı defterin: fotoğraflı anılar ve günlük ruh halin.',
  'room.despacho.desc':
    'Finans: sabit ve değişken gider ve gelirlerle bütçe, simülatörlü hedefler (finansal hesaplayıcılar, tasarruf/yatırım, borç) ve canlı piyasalar.',
  'room.biblioteca.desc': 'Sohbet ansiklopedisi: yapay zekâ sohbetleri, wiki maddeleri ve çalışma oturumları.',
  'room.entretenimiento.desc': 'Film, dizi, kitap ve masa oyunları arşivi.',
  'room.sala.desc': 'Seyahatlerini planla: güzergâh, giderler, kontrol listesi ve istek listesi.',
  'room.jardin.desc': 'Sakinlik: rehberli meditasyonlar, nefes egzersizleri ve şükran günlüğü.',
  'room.garage.desc': 'Araçlarının ve servislerinin bakımı.',
  'room.diario.desc': 'Kategoriye göre günlük haber merkezi.',
  'room.hobbies.desc': 'Uğraşların ve yaratıcı projelerin.',
  'room.idiomas.desc':
    'Dil öğren: yapay zekâ öğretmeni, aralıklı tekrarlı kelime dağarcığı, seviye müfredatı ve alıştırmalar.',
  'room.calendario.desc': 'Takvimin: gün, hafta ve aya göre etkinlikler ve rutinler.',
  'room.caminos.desc': 'Haritaya yarış pistleri, tren rayları ve hız trenleri döşe.',
  'room.canchas.desc': 'Haritaya futbol, tenis, basketbol ve beyzbol sahaları yerleştir.',
  'room.huerto.desc': 'Parseller hazırla, ekin ek, sula ve gerçek zamanlı hasat et.',
  'room.granja.desc': 'Tavuk, domuz, keçi, koyun, inek ve at yetiştir; yemlerini aynı düzenleyicide üret.',
  'room.ideas.desc':
    'Fikir günlüğün ve beyin fırtınaların, serbest tuvalde on kavram haritası biçimi (zihin haritası, ağaç, zaman çizelgesi, döngü, piramit, Venn…) ve karar vermene yardımcı sekiz diyagram (artı-eksi, güç alanı, SWOT, Eisenhower, karar ağacı, sıralama listesi, ağırlıklı karar matrisi ve Ishikawa), elle veya yapay zekâ ile.',
  'room.metas.desc':
    'Tüm evde kendine koyduklarının tamamı: alt hedefleri ve adımlarıyla hedef listesi, yapay zekânın her biri için önerdiği planlar (gerçek alt hedeflere dönüşen tarihli aşamalar) ve her şeyin zaman ekseni üzerinde kendi dönemini kapladığı zaman çizelgesi.',
  'room.computo.desc':
    'Bilgisayar odası: yanında asılı formül defteriyle (Matematik, Fizik ve Kimya hazır ve düzenlenebilir) bilimsel bir hesap makinesi ve sekiz mod — dört türlü çizici (2D, polar, parametrik ve 3D yüzey), ikilik ve on altılık taban, matrisler, denklem sistemleri, birim dönüştürme, bahşiş ve üçlü kural; ayrıca Excel ve PDF’e aktarılabilen hesap tabloları.',
