  'ideas.tipo.matriz': 'Karar matrisi',
  'ideas.tipoDesc.matriz': 'Gerçekten önemsediğin kriterlere göre puanlanan birkaç seçenek.',
  'ideas.guia.matriz':
    'Her kriter senin için ne kadar önemliyse o kadar ağırlık taşır (1-5) ve her seçenek buna göre 1’den 5’e puanlanır. Toplam, puanı ağırlıkla çarpar; böylece hiçbir şey önemsemediğin bir konuda harika olarak kazanmaz.',
  'ideas.matriz.criterio': 'Kriter',
  'ideas.matriz.opcion': 'Seçenek',
  'ideas.matriz.peso': 'Ağırlık',
  'ideas.matriz.pesoAyuda': 'Bu kriter senin için ne kadar önemli (1-5)',
