  'tut.terminar': 'Bitir',
  'tut.voz': 'Adımları sesli oku',
  'tut.appSinCuarto':
    'Bu uygulama henüz hiçbir odada değil, o yüzden sana burada anlatıyorum. Kullanmak için Menü › Şablonlar’dan ata.',
  'tut.errorCarga': 'Bu öğreticiyi yükleyemedim. Bağlantını kontrol et ve tekrar dene.',
  'tut.preparandoDemo': 'O uygulamanın yılını demo evinde hazırlıyorum; tur birkaç saniye içinde başlıyor…',
  'tut.selector.titulo': 'Hangi öğreticiyi görmek istersin?',
  'tut.selector.hint': 'Sarıyla vurgulanmış bir bölgeye dokun, ya da genel olanla başla.',
  'tut.selector.general': 'Genel öğretici',
